Demonstrate bidirectional two-pointer pair finding and in-place duplicate removal:
def two_sum_sorted(nums, target):
    left, right = 0, len(nums) - 1
    while left < right:
        curr = nums[left] + nums[right]
        if curr == target:
            return [left, right]
        elif curr < target:
            left += 1
        else:
            right -= 1
    return []
assert two_sum_sorted([2, 7, 11, 15], 9) == [0, 1]
# In-place duplicate removal:
def remove_duplicates(nums):
    if not nums: return 0
    write = 1
    for read in range(1, len(nums)):
        if nums[read] != nums[read - 1]:
            nums[write] = nums[read]
            write += 1
    return write
arr = [1, 1, 2, 2, 3]
count = remove_duplicates(arr)
assert count == 3 and arr[:3] == [1, 2, 3]
Result: Two-pointer passes achieve O(n) runtime with O(1) auxiliary space.

Demonstrate binary search in a rotated sorted array:
def search_rotated(nums, target):
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = left + (right - left) // 2
        if nums[mid] == target:
            return mid
        # Left half is sorted:
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        # Right half is sorted:
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1
    return -1
assert search_rotated([4, 5, 6, 7, 0, 1, 2], 0) == 4
assert search_rotated([4, 5, 6, 7, 0, 1, 2], 3) == -1
Result: Binary search identifies sorted halves to maintain O(log n) time.
